pm.test('this-week contains only organization-local current-week bookings', function () {
    const timeZone = body.data.timeZone;
    const today = localDate(Date.now(), timeZone);

    const [year, month, day] = today.split('-').map(Number);
    const todayUTC = new Date(Date.UTC(year, month - 1, day));

    // Monday is the first day of the week.
    const daysSinceMonday = (todayUTC.getUTCDay() + 6) % 7;

    todayUTC.setUTCDate(todayUTC.getUTCDate() - daysSinceMonday);

    const weekStart = todayUTC.toISOString().slice(0, 10);

    todayUTC.setUTCDate(todayUTC.getUTCDate() + 7);

    const nextWeekStart = todayUTC.toISOString().slice(0, 10);

    body.data.bookings.forEach(function (booking) {
        const bookingDate = localDate(booking.startsAt, timeZone);

        pm.expect(bookingDate >= weekStart && bookingDate < nextWeekStart)
            .to.eql(true);
    });
});
